// Score lead based on engagement and fit
const webhookData = items[0].json;
const lead = webhookData.body && typeof webhookData.body === 'object'
  ? webhookData.body
  : webhookData;

if (!lead.leadId) {
  throw new Error('Missing leadId in webhook payload');
}

// Extract data
const engagementScore = Number(lead.engagementScore || 0);
const demographicFit = Number(lead.demographicFit || 0);
const behavioralScore = Number(lead.behavioralScore || 0);

// Calculate weighted score
const weightedScore = (engagementScore * 0.4) + (demographicFit * 0.3) + (behavioralScore * 0.3);

// Determine score category
let scoreCategory = 'cold';
if (weightedScore >= 85) scoreCategory = 'hot';
else if (weightedScore >= 70) scoreCategory = 'warm';
else if (weightedScore >= 50) scoreCategory = 'follow-up';

// Prepare output
return [{
  json: {
    leadId: lead.leadId,
    score: Math.round(weightedScore),
    scoreCategory: scoreCategory,
    tags: [...(lead.tags || []), scoreCategory],
    scoredAt: new Date().toISOString(),
    scoringBreakdown: {
      engagement: engagementScore,
      demographic: demographicFit,
      behavioral: behavioralScore
    }
  }
}];
